Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_avacostModelCombination">_avacostModelCombination</param>
/// <returns>AVACostModelCombination</returns>
AVACostModelCombination         parmAVACostModelCombination(AVACostModelCombination         _avacostModelCombination = avaCostModelCombination)
{
    avaCostModelCombination = _avacostModelCombination;
    return avaCostModelCombination;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_bom">_bom</param>
/// <param name = "_consumptionQty">_consumptionQty</param>
/// <param name = "_parentBOMCalcItem">_parentBOMCalcItem</param>
/// <returns>BOMCalcItem</returns>
static BOMCalcItem newBOM(BOM                    _bom,
                                 Qty                    _consumptionQty,
                                 BOMCalcItem            _parentBOMCalcItem)
{
    BOMCalcItem         locBOMCalcItem = next newBOM(_bom,_consumptionQty,_parentBOMCalcItem);
    locBOMCalcItem.parmAVACostModelCombination(_parentBOMCalcItem.parmAVACostModelCombination());
    return locBOMCalcItem;
}
